#!/usr/bin/env python3
"""Strict verifier for case 02."""

from __future__ import annotations

import json
import hashlib
import sys
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "src"
ALL_OUTPUT = ROOT / "all_py_files.txt"
TODO_OUTPUT = ROOT / "todo_py_files.txt"
SUMMARY_OUTPUT = ROOT / "summary.json"
SOURCE_TREE_SHA256 = "32289f3a55559608842786c6d357c4c148221f2024b301f81d6b4fbc2a9adaaa"


def fail(message: str) -> None:
    print(f"FAIL: {message}", file=sys.stderr)
    raise SystemExit(1)


def bytewise(values: list[str]) -> list[str]:
    return sorted(values, key=lambda value: value.encode("utf-8"))


def source_tree_digest() -> str:
    digest = hashlib.sha256()
    entries = sorted(
        SOURCE.rglob("*"),
        key=lambda path: path.relative_to(SOURCE).as_posix().encode("utf-8"),
    )
    for path in entries:
        relative = path.relative_to(SOURCE).as_posix().encode("utf-8")
        if path.is_symlink():
            kind = b"L"
            data = path.readlink().as_posix().encode("utf-8")
        elif path.is_dir():
            kind = b"D"
            data = b""
        elif path.is_file():
            kind = b"F"
            data = path.read_bytes()
        else:
            kind = b"O"
            data = b""
        digest.update(kind)
        digest.update(len(relative).to_bytes(8, "big"))
        digest.update(relative)
        digest.update(len(data).to_bytes(8, "big"))
        digest.update(data)
    return digest.hexdigest()


def read_list(path: Path, label: str) -> list[str]:
    if not path.is_file():
        fail(f"{label} does not exist")
    raw = path.read_bytes()
    if not raw or not raw.endswith(b"\n"):
        fail(f"{label} must be non-empty and end with a newline")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        fail(f"{label} is not valid UTF-8: {exc}")
    lines = text[:-1].split("\n")
    if any(not line for line in lines):
        fail(f"{label} contains a blank line")
    if len(lines) != len(set(lines)):
        fail(f"{label} contains duplicate paths")
    if lines != bytewise(lines):
        fail(f"{label} is not sorted by UTF-8 byte order")
    if any("\\" in line or line.startswith("/") for line in lines):
        fail(f"{label} contains a non-canonical path")
    return lines


def main() -> None:
    if not SOURCE.is_dir():
        fail("benchmark source directory is missing")
    if source_tree_digest() != SOURCE_TREE_SHA256:
        fail("src directory was modified")

    all_expected: list[str] = []
    todo_expected: list[str] = []
    for path in SOURCE.rglob("*"):
        if path.is_symlink():
            continue
        if path.is_file() and path.suffix == ".py":
            relative = path.relative_to(SOURCE).as_posix()
            all_expected.append(relative)
            if b"TODO" in path.read_bytes():
                todo_expected.append(relative)
    all_expected = bytewise(all_expected)
    todo_expected = bytewise(todo_expected)

    all_actual = read_list(ALL_OUTPUT, "all_py_files.txt")
    todo_actual = read_list(TODO_OUTPUT, "todo_py_files.txt")
    if all_actual != all_expected:
        fail("all_py_files.txt is incomplete or contains incorrect paths")
    if todo_actual != todo_expected:
        fail("todo_py_files.txt is incomplete or contains incorrect paths")

    if not SUMMARY_OUTPUT.is_file():
        fail("summary.json does not exist")
    try:
        summary = json.loads(SUMMARY_OUTPUT.read_text(encoding="utf-8"))
    except Exception as exc:
        fail(f"summary.json is not valid JSON: {exc}")
    if not isinstance(summary, dict) or set(summary) != {
        "all_py_files",
        "todo_py_files",
    }:
        fail("summary.json must contain exactly the required fields")
    for key in ("all_py_files", "todo_py_files"):
        if isinstance(summary[key], bool) or not isinstance(summary[key], int):
            fail(f"{key} must be an integer")
    if summary["all_py_files"] != len(all_expected):
        fail("all_py_files count is incorrect")
    if summary["todo_py_files"] != len(todo_expected):
        fail("todo_py_files count is incorrect")

    print("PASS: source-file lists and counts satisfy all requirements")


if __name__ == "__main__":
    main()
